verify.cmd:
node -e 'const fs=require("fs")
const fail=(m)=>{console.error(m);process.exit(1)}
const norm=(s)=>s.replace(/\/\*[\s\S]*?\*\//g," ").replace(/^\s*\/\/.*$/gm," ")
const rd=(f)=>{try{return norm(fs.readFileSync(f,"utf8"))}catch(e){return null}}
const body=(src,sig)=>{const i=src.indexOf(sig);return i<0?"":src.slice(i,src.indexOf("\n}",i))}
const urls=rd("lib/library/asset-urls.ts")
const page=rd("app/(main)/admin/library/page.tsx")
const acts=rd("app/(main)/admin/library/actions.ts")
const pk=rd("lib/loom/picker-actions.ts")
const picker=rd("components/loom/loom-picker.tsx")
const space=rd("app/(main)/spaces/[slug]/loom/page.tsx")
if(page===null||acts===null||pk===null||picker===null||space===null)process.exit(79)
if(urls===null||!/export async function proofLibraryAssetUrl\(/.test(urls))fail("there is no proof rendition, so a protected asset is shown at full size or not at all")
const proof=body(urls,"export async function proofLibraryAssetUrl(")
if(!/libraryProofPath\(/.test(proof))fail("the proof link does not sign a stored proof object, so it can reach the master")
if(/createSignedUrl\(\s*asset\.storagePath/.test(proof)||/transform/.test(proof))fail("the proof link signs the master itself, and storage honours that token at the object route, so the original is one path edit away")
const po=rd("lib/library/proof-object.ts")
if(po===null)fail("there is no stored proof object, so a proof link can only be a signature of the master")
const pp=body(po,"export function libraryProofPath(")
if(!/LIBRARY_PROOF_PREFIX/.test(pp))fail("the proof path is not a separate object from the master")
const wp=body(po,"export async function writeLibraryProof(")
if(!/readImageDimensions\(/.test(wp)||!/LIBRARY_PROOF_WIDTH/.test(wp))fail("a stored proof is not checked for width on its own bytes, so a proof file could be the master under another name")
if(/from\s+["\x27]sharp["\x27]|import\(["\x27]sharp["\x27]\)/.test(po))fail("the proof decodes with sharp in the Loom seam, which is the og-trace fan-out")
const pa=body(acts,"export async function protectLibraryAsset(")
if(!/writeLibraryProof\(/.test(pa)||!/removeLibraryProof\(/.test(pa))fail("protecting does not write the proof, or releasing does not delete it")
if(/signedLibraryAssetUrl\(/.test(page)||!/proofLibraryAssetUrl\(/.test(page))fail("the Studio renders the signed original of a protected row instead of its proof")
if(!/withLoomProofs\(|proofLibraryAssetUrl\(/.test(body(pk,"export async function loomImages(")))fail("the picker list carries no proofs, so a protected asset is either a master in the picker or missing from it")
if(!/withLoomProofs|proofLibraryAssetUrl/.test(space))fail("the Space Loom Studio renders no proofs, so a protected asset leaves it or shows its master")
if(!/locked\s*:\s*a\.isProtected/.test(picker)||!/disabled=\{t\.locked\}/.test(picker))fail("the picker lets a protected tile be placed, so a page can store a protected asset or an expiring URL")
console.log("ok")'
